        Box::pin(async move {
            let entity = args.entity.get_entity();
            let living_entity_opt = args.entity.get_living_entity();
            if living_entity_opt.is_none()
                || entity.entity_type == &EntityType::FOX
                || entity.entity_type == &EntityType::BEE
            {
                return;
