                .await;
            let mov = if living_entity.is_player() {
                living_entity.get_movement()
            } else {
                entity.last_pos.load() - entity.pos.load()
            };
            let state_id = args.world.get_block_state_id(args.position);
            let props = NetherWartLikeProperties::from_state_id(state_id, args.block);
            if props.age == 0 {
                return;
            }
            if mov.horizontal_length_squared() <= 0.0
                || (mov.x.abs() < 0.003 && mov.z.abs() < 0.003)
            {
                return;
            }
            args.entity
                .damage(args.entity, 1.0, DamageType::SWEET_BERRY_BUSH)
                .await;
        })
    }
    fn random_tick<'a>(&'a self, args: RandomTickArgs<'a>) -> BlockFuture<'a, ()> {
        Box::pin(async move {
            // Vanilla checks the light above the bush rather than at it, so
            // this cannot rely on the generic crop tick's own check.
            if args.world.get_raw_brightness(&args.position.up(), 0) < MIN_GROWTH_LIGHT {
                return;
            }
            if rand::rng().random_range(0..5) == 0 {
                // Resolves to this type's own `CropBlockBase::random_tick` below,
